add_action( 'woocommerce_thankyou', 'perfectpixel_conversion_tracking_code', 20 );

function perfectpixel_conversion_tracking_code( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || $order->has_status( 'failed' ) || $order->get_meta( '_perfectpixel_conversion_tracked' ) ) {
		return;
	}
	$order->update_meta_data( '_perfectpixel_conversion_tracked', 1 );
	$order->save();

	$data = array(
		'id'       => $order->get_order_number(),
		'total'    => (float) $order->get_total(),
		'currency' => $order->get_currency(),
	);
	echo '<script>window.perfectpixelOrder = ' . wp_json_encode( $data ) . ';</script>';

	// Paste your tracking code between the two HTML lines. Use perfectpixelOrder.total etc.
	echo <<<'HTML'
<script>
	// Example: gtag( 'event', 'conversion', { send_to: 'AW-XXXX/YYYY', value: perfectpixelOrder.total, currency: perfectpixelOrder.currency, transaction_id: perfectpixelOrder.id } );
	console.log( 'Order tracked', window.perfectpixelOrder );
</script>
HTML;
}
